document$.subscribe(()=>{const e=document.querySelector(".md-logo"),t=document.querySelector(".md-header__title .md-header__topic:first-child .md-ellipsis");if(!e||!t)return;if(t.closest("a.pkg-home-link"))return;const o=document.createElement("a");o.className="pkg-home-link",o.href=e.getAttribute("href")||".",o.textContent=t.textContent||"nbdctools",t.replaceWith(o)});